import React, { useEffect, useMemo, useRef, useState } from 'react';
import { casesAPI, openingsAPI } from '../services/api';
import ImageWithFallback from './ImageWithFallback';
import './CaseOpeningAnimation.css';

const SLOT_WIDTH = 150;
const WINNER_INDEX = 38;
const TOTAL_SLOTS = 56;
const ANIMATION_MS = 5600;

const CaseOpeningAnimation = ({ caseId, onComplete, onClose }) => {
  const [caseData, setCaseData] = useState(null);
  const [openingResult, setOpeningResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [animating, setAnimating] = useState(false);
  const [finished, setFinished] = useState(false);
  const [translateX, setTranslateX] = useState(0);
  const viewportRef = useRef(null);
  const completedRef = useRef(false);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setError('');
      try {
        const caseResponse = await casesAPI.getCaseById(caseId);
        if (cancelled) return;
        setCaseData(caseResponse.data);
        const openingResponse = await openingsAPI.openCase(caseId);
        if (cancelled) return;
        setOpeningResult(openingResponse.data);
      } catch (err) {
        if (!cancelled) setError(err.response?.data?.detail || 'Unable to open this case.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    if (caseId) load();
    return () => { cancelled = true; };
  }, [caseId]);

  const wonItem = useMemo(() => openingResult?.item || null, [openingResult]);

  const sequence = useMemo(() => {
    if (!caseData?.items?.length || !wonItem) return [];
    const pool = caseData.items;
    return Array.from({ length: TOTAL_SLOTS }, (_, index) => {
      if (index === WINNER_INDEX) return wonItem;
      const candidates = pool.filter((item) => item.id !== wonItem.id);
      return (candidates.length ? candidates : pool)[Math.floor(Math.random() * (candidates.length || pool.length))];
    });
  }, [caseData, wonItem]);

  useEffect(() => {
    if (!sequence.length || !wonItem) return undefined;
    const viewportWidth = viewportRef.current?.clientWidth || 820;
    const winnerCenter = WINNER_INDEX * SLOT_WIDTH + SLOT_WIDTH / 2;
    const target = Math.round(viewportWidth / 2 - winnerCenter);
    setTranslateX(0);
    const startTimer = window.setTimeout(() => {
      setAnimating(true);
      requestAnimationFrame(() => setTranslateX(target));
    }, 300);
    const finishTimer = window.setTimeout(() => {
      setAnimating(false);
      setFinished(true);
      if (!completedRef.current) {
        completedRef.current = true;
        onComplete?.(wonItem);
      }
    }, 300 + ANIMATION_MS);
    return () => {
      window.clearTimeout(startTimer);
      window.clearTimeout(finishTimer);
    };
  }, [sequence, wonItem, onComplete]);

  if (loading) return <div className="opening-animation-container opening-state"><div className="opening-loader" /><p>Preparing your drop…</p></div>;
  if (error || !caseData || !wonItem) return <div className="opening-animation-container opening-state"><h4>Opening unavailable</h4><p>{error || 'The opening result is incomplete.'}</p><button className="btn btn-outline-light" onClick={onClose}>Close</button></div>;

  const rarityClass = (rarity) => rarity ? `rarity-${rarity.toLowerCase().replace(/\s+/g, '-')}` : 'rarity-default';

  return (
    <div className={`opening-animation-container ${animating ? 'is-animating' : ''} ${finished ? 'is-finished' : ''}`}>
      <div className="opening-header">
        <span className="opening-kicker">WELLCASE DROP</span>
        <h3>{caseData.name}</h3>
        <p>{Number(caseData.price).toLocaleString()} € · Fair random drop</p>
      </div>
      <div className="opening-viewport" ref={viewportRef}>
        <div className="opening-pointer" aria-hidden="true" />
        <div className="opening-track" style={{ width: `${sequence.length * SLOT_WIDTH}px`, transform: `translate3d(${translateX}px,0,0)` }}>
          {sequence.map((item, index) => (
            <div className="opening-slide-item" key={`${item.id}-${index}`} style={{ width: SLOT_WIDTH }}>
              <div className="opening-item-card">
                <ImageWithFallback src={item.image_url} alt={item.name} className="opening-item-image" />
                <div className="item-name" title={item.name}>{item.name}</div>
                <div className={`item-rarity ${rarityClass(item.rarity)}`}>{item.rarity}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="opening-status">
        {!finished ? <><span className="status-label">{animating ? 'ROLLING' : 'GET READY'}</span><strong>{animating ? 'Your drop is on the way…' : 'The wheel is loading…'}</strong></> : <><span className="status-label">YOU WON</span><strong>{wonItem.name}</strong></>}
      </div>
      {finished && (
        <div className="won-item-display">
          <div className="won-item-glow"><ImageWithFallback src={wonItem.image_url} alt={wonItem.name} className="won-item-image" /></div>
          <div className="won-item-name">{wonItem.name}</div>
          <div className={`won-item-rarity ${rarityClass(wonItem.rarity)}`}>{wonItem.rarity} · {Number(wonItem.virtual_value).toLocaleString()} €</div>
          <button className="btn btn-primary mt-4 px-5" onClick={onClose}>COLLECT</button>
        </div>
      )}
    </div>
  );
};

export default CaseOpeningAnimation;
